 "content": "def transform(grid):
    # Count separate horizontal runs of each non-background color; compact to 2x3 cells.
    from collections import Counter
    counts = Counter()
    for row in grid:
        c = 0
        while c < len(row):
            if row[c] == 0:
                c += 1
                continue
            color = row[c]
            counts[color] += 1
            while c < len(row) and row[c] == color:
                c += 1
    cells = []
    for color in sorted(counts, key=lambda x: (-counts[x], x)):
        cells.extend([color] * counts[color])
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
